import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def extract_receipt_data(receipt_url: str):
    endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_analysis_client.begin_analyze_document_from_url(
        "prebuilt-receipt", receipt_url
    )
    receipts = poller.result()

    extracted_data = {
        "merchant_name": None,
        "tax": None,
        "total": None,
        "items": []
    }

    if receipts.documents:
        for receipt in receipts.documents:
            if receipt.doc_type == "prebuilt:receipt":
                extracted_data["merchant_name"] = receipt.fields.get("MerchantName", {}).get("valueData", {}).get("text")
                extracted_data["tax"] = receipt.fields.get("TotalTax", {}).get("value")
                extracted_data["total"] = receipt.fields.get("Total", {}).get("value")

                if "Items" in receipt.fields:
                    for item in receipt.fields["Items"].get("value", []):
                        item_data = {
                            "description": item.get("valueData", {}).get("text"),
                            "quantity": item.get("value", {}).get("Quantity", {}).get("value"),
                            "price": item.get("value", {}).get("Price", {}).get("value"),
                            "total_price": item.get("value", {}).get("TotalPrice", {}).get("value")
                        }
                        extracted_data["items"].append(item_data)
                break # Assuming one receipt per document for simplicity

    return extracted_data
